{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Vinorelbine, a large complex vinca alkaloid with multiple fused rings and a basic amine, has an absolute oral bioavailability of 43±13% in patients, directly demonstrating that structurally complex polycyclic alkaloids can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Minocycline, a large fused-ring polycyclic antibiotic, exhibits 90–100% oral bioavailability, showing that high molecular complexity does not preclude high oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Rifapentine, a large lipophilic polycyclic ansamycin, has an absolute oral bioavailability of 70% in healthy volunteers, supporting high F for large complex molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Ondansetron, a heteroaromatic drug with moderate first-pass metabolism, has an oral bioavailability of about 60%, supporting the expectation that the query's heteroaromatic/amine features are compatible with F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "The structurally related indolocarbazole glycoside LCS1269 is reported to have predicted human intestinal absorption corresponding to bioavailability greater than 30%, consistent with the experimental analogues and the query's fused indole/carbazole-like core.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental analogues with high transfer scores show oral bioavailability values above the 20% threshold, including large complex polycyclic alkaloids and antibiotics. No affirmative evidence supports F < 20% for the query, so the prediction is high.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement is available for the query molecule.",
    "No query-specific data on solubility, permeability, first-pass metabolism, or transporter-mediated efflux are provided.",
    "Some analogue values are variable and include individuals below 20%, but central estimates consistently exceed the threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

